package cn.mop.adapters.notification;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import java.net.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.*;
import static org.junit.jupiter.api.Assertions.*;

class PublicWebhookTransportTest {
    final URI endpoint=URI.create("https://notify.example.com/hook");
    final Set<String> domains=Set.of("notify.example.com");
    InetAddress ip(String s)throws Exception{return InetAddress.getByName(s);}
    PublicWebhookTransport transport(Dns dns){return new PublicWebhookTransport(endpoint,domains,dns);}
    @ParameterizedTest @ValueSource(strings={"http://notify.example.com/hook","https://notify.example.com:8443/hook","https://notify.example.com@evil.example/hook","https://notify.example.com/hook?secret=x","https://notify.example.com/hook#x","https://127.0.0.1/hook","https://[::1]/hook","https://notify.example.com.evil.example/hook","https://notify.example.com./hook","https://localhost/hook"})
    void unsafeEndpointRejectedBeforeDns(String url){assertThrows(PublicWebhookTransport.Failure.class,()->new PublicWebhookTransport(URI.create(url),domains,h->{fail("must not resolve");return List.of();}));}
    @ParameterizedTest @ValueSource(strings={"0.1.2.3","10.1.2.3","100.64.0.1","100.127.255.254","127.0.0.1","169.254.169.254","172.16.0.1","172.31.255.255","192.0.0.9","192.0.2.1","192.88.99.1","192.168.1.1","198.18.0.1","198.19.255.255","198.51.100.1","203.0.113.1","224.0.0.1","240.0.0.1","255.255.255.255","::1","fc00::1","2001:4860:4860::8888"})
    void nonSupportedOrSpecialAddressesRejected(String address)throws Exception{assertFalse(PublicWebhookTransport.allowedAddress(ip(address)));}
    @Test void publicIpv4CandidateOnly(){assertDoesNotThrow(()->{assertTrue(PublicWebhookTransport.allowedAddress(ip("8.8.8.8")));assertTrue(PublicWebhookTransport.allowedAddress(ip("1.1.1.1")));});}
    @Test void onePrivateAnswerRejectsWholeSet()throws Exception{var publicIp=ip("8.8.8.8");var privateIp=ip("10.0.0.1");assertThrows(PublicWebhookTransport.Failure.class,()->transport(h->List.of(publicIp,privateIp)).resolve());}
    @Test void emptyFailedAndOversizedDnsFailClosed()throws Exception{assertThrows(PublicWebhookTransport.Failure.class,()->transport(h->List.of()).resolve());assertThrows(PublicWebhookTransport.Failure.class,()->transport(h->{throw new UnknownHostException("private internal detail");}).resolve());var a=ip("8.8.8.8");assertThrows(PublicWebhookTransport.Failure.class,()->transport(h->Collections.nCopies(17,a)).resolve());}
    @Test void approvedResolutionPinnedWithoutSecondLookup()throws Exception{var count=new AtomicInteger();var address=ip("8.8.8.8");var t=transport(h->{count.incrementAndGet();return List.of(address);});var pinned=t.resolve();var c=t.client(pinned);try{assertEquals(pinned,c.dns().lookup("notify.example.com"));assertEquals(pinned,c.dns().lookup("notify.example.com"));assertEquals(1,count.get());assertThrows(UnknownHostException.class,()->c.dns().lookup("other.example.com"));assertThrows(UnsupportedOperationException.class,()->pinned.clear());}finally{c.connectionPool().evictAll();c.dispatcher().executorService().shutdown();}}
    @Test void transportDoesNotFollowRedirectRetryOrProxy()throws Exception{var t=transport(h->List.of());var c=t.client(List.of(ip("8.8.8.8")));try{assertFalse(c.followRedirects());assertFalse(c.followSslRedirects());assertFalse(c.retryOnConnectionFailure());assertEquals(Proxy.NO_PROXY,c.proxy());assertEquals(List.of(Protocol.HTTP_1_1),c.protocols());assertSame(okhttp3.Authenticator.NONE,c.authenticator());assertSame(okhttp3.Authenticator.NONE,c.proxyAuthenticator());assertEquals(10000,c.callTimeoutMillis());}finally{c.connectionPool().evictAll();c.dispatcher().executorService().shutdown();}}
    @Test void signedBodyIsImmutableAndOneShot()throws Exception{var t=transport(h->List.of());var body="{}".getBytes();var id=UUID.randomUUID();var r=t.request(id,body,Map.of("X-Notification-Signature","v1=sample-test-signature"));body[0]='x';assertTrue(r.body().isOneShot());var b=new okio.Buffer();r.body().writeTo(b);assertEquals("{}",b.readUtf8());assertEquals(id.toString(),r.header("X-Notification-Request-Id"));assertEquals("POST",r.method());}
    @Test void callerCannotInjectHostCookieOrAuthorization(){var t=transport(h->List.of());for(String header:List.of("Host","Authorization","Cookie","Content-Length","X-Notification-Request-Id"))assertThrows(PublicWebhookTransport.Failure.class,()->t.request(UUID.randomUUID(),new byte[]{1},Map.of("X-Notification-Signature","test",header,"bad")));}
    @Test void unsignedOversizedOrControlHeadersRejected(){var t=transport(h->List.of());assertThrows(PublicWebhookTransport.Failure.class,()->t.request(UUID.randomUUID(),new byte[]{1},Map.of()));assertThrows(PublicWebhookTransport.Failure.class,()->t.request(UUID.randomUUID(),new byte[65537],Map.of("X-Notification-Signature","x")));assertThrows(PublicWebhookTransport.Failure.class,()->t.request(UUID.randomUUID(),new byte[]{1},Map.of("X-Notification-Signature","x\r\nHost: bad")));}
    @Test void noWildcardOrAmbiguousAllowlist(){assertThrows(PublicWebhookTransport.Failure.class,()->new PublicWebhookTransport(endpoint,Set.of("*.example.com")));assertThrows(PublicWebhookTransport.Failure.class,()->new PublicWebhookTransport(endpoint,Set.of("NOTIFY.EXAMPLE.COM")));assertThrows(PublicWebhookTransport.Failure.class,()->new PublicWebhookTransport(endpoint,Set.of()));}
    @Test void observationNeverMeansDeliveredAndDoesNotPrintBody(){byte[] b="sensitive".getBytes();var o=new PublicWebhookTransport.Observation(200,b);b[0]='x';assertFalse(o.delivered());assertEquals("sensitive",new String(o.body()));o.body()[0]='x';assertEquals("sensitive",new String(o.body()));assertFalse(o.toString().contains("sensitive"));assertFalse(transport(h->List.of()).toString().contains("notify.example"));}
    @Test void dnsLookupHasBoundedWaitWithoutNetwork(){var t=new PublicWebhookTransport(endpoint,domains,h->{try{Thread.sleep(1000);}catch(InterruptedException ignored){Thread.currentThread().interrupt();}return List.of();},10);assertTimeoutPreemptively(java.time.Duration.ofSeconds(1),()->assertThrows(PublicWebhookTransport.Failure.class,t::resolve));}
    @Test void serviceUnavailableCannotTriggerImmediateRetry()throws Exception{var t=transport(h->List.of());var c=t.client(List.of(ip("8.8.8.8")));try{var request=t.request(UUID.randomUUID(),new byte[]{1},Map.of("X-Notification-Signature","test"));var chain=org.mockito.Mockito.mock(Interceptor.Chain.class);org.mockito.Mockito.when(chain.request()).thenReturn(request);var response=new Response.Builder().request(request).protocol(Protocol.HTTP_1_1).code(503).message("unavailable").header("Retry-After","0").build();org.mockito.Mockito.when(chain.proceed(request)).thenReturn(response);var result=c.networkInterceptors().get(0).intercept(chain);assertEquals(503,result.code());assertNull(result.header("Retry-After"));org.mockito.Mockito.verify(chain,org.mockito.Mockito.times(1)).proceed(request);}finally{c.connectionPool().evictAll();c.dispatcher().executorService().shutdown();}}
}
